let lastStepUsage = { promptTokens: 0, completionTokens: 0 };

for await (const { text, usage } of generateTextStream({
  model: yourModel,
  tools: yourTools,
  prompt: '...',
})) {
  lastStepUsage = usage; // This will be the most recent step's usage
}
```

