Use `p-limit` to control concurrency when embedding thousands of chunks:

```ts
import { embed } from 'ai';
import pLimit from 'p-limit';

// Create a limiter with max 5 concurrent requests
const limit = pLimit(5);

async function embedChunks(chunks: string[]) {
  const embeddings = await Promise.all(
    chunks.map(chunk =>
      limit(() =>
        embed({
          model: yourEmbeddingModel, // e.g., 'text-embedding-3-small'
          value: chunk,
        })
      )
    )
  );

  return embeddings.map(e => e.embedding);
}

// Usage
const chunks = Array(5000).fill('Sample document chunk...');
const embeddings = await embedChunks(chunks);
```

Alternative without external dependencies (using native async/await):

```ts
async function embedChunks(chunks: string[], concurrency = 5) {
  const results: number[][] = [];
  const executing: Promise<void>[] = [];

  for (const chunk of chunks) {
    const p = embed({ model: yourEmbeddingModel, value: chunk })
      .then(e => results.push(e.embedding));
    executing.push(p);

    if (executing.length >= concurrency) {
      await Promise.race(executing);
    }
  }

  await Promise.all(executing);
  return results;
}
```

